// B"H
const fs = require("fs");
const path = require("path");
const { safePath } = require("../pathGuard.js");
const { readText, writeText } = require("../readWrite.js");
const { runActionBatch } = require("../actionBatch.js");

function lineCol(text, index) {
  const before = text.slice(0, index).split(/\r?\n/);
  return { line: before.length, column: before[before.length - 1].length };
}

function findBrace(text, open) {
  let depth = 0, quote = null, esc = false;
  for (let i = open; i < text.length; i++) {
    const ch = text[i];
    if (quote) { if (esc) esc = false; else if (ch === "\\") esc = true; else if (ch === quote) quote = null; continue; }
    if (ch === "'" || ch === '"' || ch === "`") { quote = ch; continue; }
    if (ch === "{") depth++;
    if (ch === "}" && --depth === 0) return i;
  }
  return -1;
}

function outlineText(text, p = ".") {
  const imports = [...text.matchAll(/\b(?:import\s+(?:[^'\"]+\s+from\s+)?|export\s+[^'\"]+\s+from\s+|import\s*\(\s*)['\"]([^'\"]+)['\"]/g)].map(m => ({ spec: m[1], loc: lineCol(text, m.index) })).slice(0, 500);
  const variables = [...text.matchAll(/\b(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)\b/g)].map(m => ({ name: m[1], loc: lineCol(text, m.index) })).slice(0, 500);
  const symbols = [];
  const re = /(^|\n)([ \t]*(?:(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)\s*\([^)]*\)\s*\{|(?:export\s+)?class\s+([A-Za-z_$][\w$]*)\s*[^\{]*\{|(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>))/g;
  let m;
  while ((m = re.exec(text))) {
    const name = m[3] || m[4] || m[5];
    const start = m.index + (m[1] ? 1 : 0);
    const open = text.indexOf("{", re.lastIndex - 1);
    const close = open >= 0 ? findBrace(text, open) : -1;
    symbols.push({ name, kind: m[3] ? "function" : m[4] ? "class" : "arrow", loc: lineCol(text, start), range: { start, end: close >= 0 ? close + 1 : re.lastIndex }, bodyRange: open >= 0 && close >= 0 ? { start: open + 1, end: close } : null });
  }
  return { ok: true, action: "astOutline", parser: "agent-regex-balanced", path: p, imports, variables, symbols };
}

async function astOutline(config, payload) {
  const p = payload.path || payload.p || ".";
  const got = await readText(config, p, payload.maxChars || 1000000, 0);
  return outlineText(got.content || "", p);
}

async function astEdit(config, payload) {
  const p = payload.path || payload.p;
  const got = await readText(config, p, 10000000, 0);
  const text = got.content || "";
  const outline = outlineText(text, p);
  const symbol = outline.symbols.find(s => s.name === (payload.name || payload.functionName || payload.symbol));
  if (!symbol) return { ok: false, action: payload.action, error: "symbol_not_found", symbols: outline.symbols.map(s => s.name) };
  const content = String(payload.content ?? payload.replacement ?? payload.body ?? "");
  let next;
  if (payload.action === "replaceFunctionBody") next = text.slice(0, symbol.bodyRange.start) + "\n" + content + "\n" + text.slice(symbol.bodyRange.end);
  else if (payload.action === "insertBeforeFunction") next = text.slice(0, symbol.range.start) + content + "\n" + text.slice(symbol.range.start);
  else if (payload.action === "insertAfterFunction") next = text.slice(0, symbol.range.end) + "\n" + content + text.slice(symbol.range.end);
  else next = text.slice(0, symbol.range.start) + content + text.slice(symbol.range.end);
  const wrote = await writeText(config, p, next);
  return { ok: true, action: payload.action, editedSymbol: symbol, ...wrote, astOutline: outlineText(next, p) };
}

function report(action, config, payload) {
  const root = safePath(config, payload.path || payload.p || ".");
  const packageJson = path.join(root, "package.json");
  const hasPackage = fs.existsSync(packageJson);
  return { ok: true, action, target: root, checks: { hasPackageJson: hasPackage, exists: fs.existsSync(root) }, suggestedNext: ["astOutline", "dependencyGraph", "simulateRuntime", "actionBatch"] };
}

function buildQualityActions(ctx, buildActions) {
  const { config, payload, ws } = ctx;
  const simple = name => async () => report(name, config, payload);
  return {
    astOutline: async () => astOutline(config, payload),
    replaceFunction: async () => astEdit(config, payload),
    replaceFunctionBody: async () => astEdit(config, payload),
    insertBeforeFunction: async () => astEdit(config, payload),
    insertAfterFunction: async () => astEdit(config, payload),
    testMatrix: async () => runActionBatch({ ...payload, steps: payload.cases || payload.steps || [] }, async next => buildActions(config, next, ws)[next.action]()),
    bundleTrace: simple("bundleTrace"),
    dependencyCycleCheck: simple("dependencyCycleCheck"),
    deadExportScan: simple("deadExportScan"),
    mutationPatchTest: simple("mutationPatchTest"),
    browserReplay: async () => buildActions(config, { ...payload, action: "simulateRuntime", runtime: "browser" }, ws).simulateRuntime(),
    apiContractCheck: simple("apiContractCheck"),
    perfBudgetCheck: simple("perfBudgetCheck")
  };
}

module.exports = { buildQualityActions, outlineText };

// B"H
const { stabilizeRemoteModuleSource } = require("./remoteModuleCompat.js");
const { buildRuntimeVirtualEnv } = require("../runtimeVirtualEnv.js");

function json64(value, fallback) {
  if (!value) return fallback;
  try {
    return JSON.parse(Buffer.from(String(value), "base64").toString("utf8"));
  } catch (_) {
    return fallback;
  }
}

function jsonMaybe(value, fallback) {
  if (value == null || value === "") return fallback;
  if (typeof value === "object") return value;
  try {
    return JSON.parse(String(value));
  } catch (_) {
    return fallback;
  }
}

function collectOptions(payload = {}, config = {}) {
  const env = buildRuntimeVirtualEnv(payload, config);
  return {
    runtime: payload.runtime || "browser",
    engine: payload.engine || "merkava",
    entry: env.entry || payload.entry || payload.path || payload.p || payload.target || "index.html",
    files: Object.keys(env.files || {}).length ? env.files : jsonMaybe(payload.files, json64(payload.files64, {})),
    virtualEnv: env,
    workflow: jsonMaybe(
      payload.workflow,
      payload.steps && payload.steps.length ? { steps: payload.steps } : json64(payload.workflow64, null)
    ),
    probes: jsonMaybe(payload.probes, json64(payload.probes64, [])),
    interactions: jsonMaybe(payload.interactions, json64(payload.interactions64, [])),
    origin: payload.origin || process.env.AWTSMOOS_BASE_URL || "https://awtsmoos.com",
    url: payload.url || process.env.AWTSMOOS_BASE_URL || "https://awtsmoos.com",
    headless: payload.headless !== false,
    waitMs: Number(payload.waitMs || 800),
    timeoutMs: Number(payload.timeoutMs || 30000)
  };
}

function resolveMerkavaServiceUrl(payload = {}) {
  const base = payload.origin || payload.url || process.env.AWTSMOOS_BASE_URL || "https://awtsmoos.com";
  return new URL("/scripts/awtsmoos/MerkavaExecutor/merkava-service/index.js", base).href;
}

const moduleCache = new Map();

async function fetchText(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed loading remote Merkava module ${url}: HTTP ${response.status}`);
  }
  return await response.text();
}

function rewriteImports(source, baseUrl) {
  return String(source || "").replace(
    /(import\s+[^"']*?["']|export\s+[^"']*?from\s+["'])(\.{1,2}\/[^"']+)(["'])/g,
    (_, prefix, rel, suffix) => `${prefix}${new URL(rel, baseUrl).href}${suffix}`
  );
}

function collectRemoteDeps(source, baseUrl) {
  const deps = new Set();
  for (const match of String(source || "").matchAll(/(?:import|export)\s+[^"']*?["'](https?:\/\/[^"']+)["']/g)) deps.add(match[1]);
  for (const match of String(source || "").matchAll(/require\(["'](\.{1,2}\/[^"']+)["']\)/g)) deps.add(new URL(match[1], baseUrl).href);
  return [...deps];
}

async function importHttpModule(url) {
  if (moduleCache.has(url)) {
    const cached = await moduleCache.get(url);
    return cached.module || cached;
  }

  const pending = (async () => {
    let source = await fetchText(url);
    source = stabilizeRemoteModuleSource(source, url);
    source = rewriteImports(source, url);

    const deps = collectRemoteDeps(source, url);

    for (const dep of deps) {
      await importHttpModule(dep);
    }

    source = source.replace(/(["'])(https?:\/\/[^"']+)(["'])/g, (_, q1, dep, q2) => {
      const cached = moduleCache.get(dep);
      if (!cached || !cached.dataUrl) return `${q1}${dep}${q2}`;
      return `${q1}${cached.dataUrl}${q2}`;
    });

    const dataUrl = "data:text/javascript;base64," + Buffer.from(source, "utf8").toString("base64");
    const mod = await import(dataUrl);
    const resolved = { module: mod, dataUrl };
    moduleCache.set(url, resolved);
    return resolved;
  })();

  moduleCache.set(url, pending);
  const resolved = await pending;
  return resolved.module;
}

async function loadMerkavaService(payload = {}) {
  return await importHttpModule(resolveMerkavaServiceUrl(payload));
}

function fallback(error, payload) {
  return {
    ok: false,
    engine: "merkava",
    error: "merkava_runtime_failed",
    message: error && error.message ? error.message : String(error),
    stack: error && error.stack ? error.stack : "",
    retryWith: "chrome",
    chromeRecommended: true,
    suggestion: {
      action: "simulateRuntime",
      engine: "chrome",
      reason: "Merkava runtime failed; retry with browser-backed runtime."
    },
    options: collectOptions(payload, {})
  };
}

async function runService(payload, method, config = {}) {
  const options = collectOptions(payload, config);
  if (options.virtualEnv?.diagnostics?.length) {
    return { ok: false, action: method, engine: "merkava", error: "runtime_preflight_failed", diagnostics: options.virtualEnv.diagnostics, options };
  }
  try {
    const service = await loadMerkavaService(payload);
    const fn = service && service[method];
    if (typeof fn !== "function") {
      throw new Error(`Remote Merkava service missing method: ${method}`);
    }
    const result = await fn(options);
    return { ...result, virtualEnv: options.virtualEnv };
  } catch (error) {
    return fallback(error, payload);
  }
}

function buildRuntimeActions(ctx) {
  const { payload, config } = ctx;

  return {
    async simulateRuntime() {
      return await runService(payload, "simulateRuntime", config);
    },

    async runtimeWorkflow() {
      return await runService(payload, "runtimeWorkflow", config);
    },

    async merkavaWorkflowRun() {
      return await runService(payload, "runtimeWorkflow", config);
    },

    async aiWorkflowRun() {
      return await runService(payload, "runtimeWorkflow", config);
    },


    async testRuntimeOnce() {
      return await runService(payload, "simulateRuntime", config);
    }
  };
}

module.exports = { buildRuntimeActions };

